    loft(context, id + "loft1", { "sheetProfilesArray" : [{ "sheetProfileEntities" : qSketchRegion(id + "p0") }, { "sheetProfileEntities" : qSketchRegion(id + "p1") }], "bodyType" : ExtendedToolBodyType.SOLID, "operationType" : NewBodyOperationType.NEW, "startCondition" : LoftEndDerivativeType.DEFAULT, "endCondition" : LoftEndDerivativeType.DEFAULT, "matchConnections" : true, "connections" : [{ "connectionEntities" : qUnion([qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "p0", EntityType.BODY), BodyType.SHEET), EntityType.VERTEX), vector(10, 10, 0) * millimeter), qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "p1", EntityType.BODY), BodyType.SHEET), EntityType.VERTEX), vector(10, 0, 20) * millimeter)]), "connectionEdgeQueries" : qUnion([]), "connectionEdgeParameters" : [] }, { "connectionEntities" : qUnion([qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "p0", EntityType.BODY), BodyType.SHEET), EntityType.VERTEX), vector(-10, -10, 0) * millimeter), qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "p1", EntityType.BODY), BodyType.SHEET), EntityType.VERTEX), vector(-10, 0, 20) * millimeter)]), "connectionEdgeQueries" : qUnion([]), "connectionEdgeParameters" : [] }] });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "loft1", EntityType.BODY), BodyType.SOLID)), "volume" : roundToPrecision(evVolume(context, { "entities" : qBodyType(qCreatedBy(id + "loft1", EntityType.BODY), BodyType.SOLID) }) / millimeter ^ 3, 6) };
}

